[asy]
size(150);
real r=1/(2sqrt(2)+1);
path square=(0,1)--(r,1)--(r,1-r)--(0,1-r)--cycle;
path square2=(0,.5)--(r/sqrt(2),.5+r/sqrt(2))--(r*sqrt(2),.5)--(r/sqrt(2),.5-r/sqrt(2))--cycle;
